   709  /*
   710   * 'copy_stack()' - Copy the top N stack objects.
   711   */
   712
   713  static int                              /* O - 0 on success, -1 on error */
   714  copy_stack(_cups_ps_stack_t *st,        /* I - Stack */
   715             int              c)          /* I - Number of objects to copy */
   716  {
   717    int   n;                              /* Index */
   718
   719
   720    if (c < 0)
   721      return (-1);
   722    else if (c == 0)
   723      return (0);
   724
   725    if ((n = st->num_objs - c) < 0)
   726      return (-1);
   727
   728    while (c > 0)
   729    {
   730      if (!push_stack(st, st->objs + n))
   731        return (-1);
   732
   733      n ++;
   734      c --;
   735    }
   736
   737    return (0);
   738  }
